export const prerender = false;

import NotFoundPlaygroundIsland from "@/components/NotFoundPlaygroundIsland.astro";
import PostNavigation from "@/components/PostNavigation.astro";
import RelatedPosts from "@/components/RelatedPosts.astro";
import BackToTop from "@/components/ui/BackToTop.astro";
import Tag from "@/components/ui/Tag.astro";
import { SITE } from "@/config/site";
import { getContentBucket } from "@/lib/content/bindings";
import { blogNeighbors, listBlogPosts, loadBlogPost } from "@/lib/content/blog";
import { BLOG_HTML_CACHE_CONTROL } from "@/lib/content/cache";
import Layout from "@/layouts/Layout.astro";
import { formatBlogSurfaceDate, toDatetimeAttr } from "@/utils/date";
import { formatReadingTime, getReadingTime } from "@/utils/reading-time";
import {
	generateArticleItemListSchema,
	generateBlogPostingSchema,
	generateBreadcrumbSchema,
	stringifySchema,
} from "@/utils/schema";

const slug = Astro.params.id ?? "";
const bucket = await getContentBucket();
const post = bucket ? await loadBlogPost(bucket, slug) : null;
const allPosts = bucket ? await listBlogPosts(bucket) : [];

if (!post) {
	// on-demand から prerender の /404 へ rewrite は Astro 7 server では禁止
	Astro.response.status = 404;
}

const neighbors = post ? blogNeighbors(allPosts, slug) : undefined;
const title = post?.title ?? "";
const excerpt = post?.excerpt ?? "";
const publish_date = post?.publish_date ?? new Date(0);
const revise_date = post?.revise_date;
const tags = post?.tags ?? [];
const body = post?.body ?? "";
const html = post?.html ?? "";

const readingTime = getReadingTime(body);
const readingTimeText = formatReadingTime(readingTime);
const publishedTime = toDatetimeAttr(publish_date);
const modifiedTime = revise_date ? toDatetimeAttr(revise_date) : publishedTime;
const ogImageURL = new URL(`/og/blog/${slug}.png`, Astro.site);
const site = Astro.site?.href || SITE.url;
const blogSchema = generateBlogPostingSchema(site, {
	slug,
	title,
	excerpt,
	date: publish_date,
	updatedDate: revise_date,
	tags,
	image: ogImageURL.href,
	body,
});
const breadcrumbSchema = generateBreadcrumbSchema(site, [
	{ name: "Blog", path: "/blog/" },
	{ name: title || "Blog", path: `/blog/${slug}/` },
]);
const itemListSchema = generateArticleItemListSchema(body);

if (post) {
	Astro.response.headers.set("Cache-Control", BLOG_HTML_CACHE_CONTROL);
}
---

{
  !post ? (
    <Layout
      title={`404 - ページが見つかりません | ${SITE.name}`}
      description="お探しのページは見つかりませんでした。"
      noindex
      omitCanonical
      noHeader
      noFooter
      flushTop
    >
      <NotFoundPlaygroundIsland />
    </Layout>
  ) : (
<Layout
  title={`${title} | Blog | ${SITE.name}`}
