import { basename } from "node:path";
import { parseAccent } from "./accent.ts";
import { materializeSlideHtml } from "./clicks.ts";
import { findForbidden } from "./forbidden.ts";
import { markdownToHtml } from "./markdown.ts";
import { splitSlides } from "./split-slides.ts";
import {
	DECK_FRONTMATTER_KEYS,
	DeckError,
	isColorTheme,
	isDeckEffect,
	isSlideType,
	REQUIRED_FRONTMATTER_KEYS,
	type ColorTheme,
	type Deck,
	type DeckEffect,
	type DeckFrontmatter,
	type Slide,
	type SlideType,
} from "./types.ts";
const TYPE_AT_START = /^\s*<!--\s*type:\s*([a-z]+)\s*-->\s*/;
const NOTES_BLOCK = /<!--\s*notes\b([\s\S]*?)-->/g;
const COLUMN_MARK = /<!--\s*column\s*-->/;
const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;
function parseYamlBlock(text: string): Record<string, unknown> {
	const data: Record<string, unknown> = {};
	for (const rawLine of text.split("\n")) {
		const line = rawLine.trimEnd();
		if (line.trim() === "" || line.trim().startsWith("#")) {
			continue;
		}
		const idx = line.indexOf(":");
		if (idx === -1) {
			throw new DeckError(`frontmatter を解釈できません: ${line}`);
		}
		const key = line.slice(0, idx).trim();
		let value = line.slice(idx + 1).trim();
		if (
			(value.startsWith('"') && value.endsWith('"')) ||
			(value.startsWith("'") && value.endsWith("'"))
		) {
			value = value.slice(1, -1);
		}
		data[key] = value;
	}
	return data;
}
function parseFrontmatter(
	data: Record<string, unknown>,
	filename?: string,
): DeckFrontmatter {
	const keys = Object.keys(data);
	const allowed = new Set<string>(DECK_FRONTMATTER_KEYS);
	const unknown = keys.filter((key) => !allowed.has(key));
	if (unknown.length > 0) {
		throw new DeckError(
			`frontmatter に見た目または未知のキーがあります: ${unknown.join(", ")}`,
		);
	}
	for (const key of REQUIRED_FRONTMATTER_KEYS) {
		const value = data[key];
		if (typeof value !== "string" || value.trim() === "") {
			throw new DeckError(`frontmatter の ${key} は必須です`);
		}
	}
	const title = String(data.title).trim();
	const date = String(data.date).trim();
	const description = String(data.description).trim();
	const slug = String(data.slug).trim();
	let theme: ColorTheme = "dark";
	if (data.theme !== undefined) {
		const raw = String(data.theme).trim().toLowerCase();
		if (!isColorTheme(raw)) {
			throw new DeckError(`theme は light か dark です: ${String(data.theme)}`);
		}
		theme = raw;
	}
	if (!DATE_PATTERN.test(date)) {
		throw new DeckError(`date は YYYY-MM-DD にしてください: ${date}`);
	}
	if (!SLUG_PATTERN.test(slug)) {
		throw new DeckError(`slug は英小文字・数字・ハイフンだけです: ${slug}`);
	}
	if (filename) {
		const fromFile = basename(filename, ".md");
		if (fromFile !== slug) {
			throw new DeckError(
				`ファイル名 ${fromFile}.md と slug ${slug} が一致しません`,
			);
		}
	}
	const event =
		data.event !== undefined ? String(data.event).trim() : undefined;
	const talkSlug =
		data.talkSlug !== undefined ? String(data.talkSlug).trim() : undefined;
	let unlisted = false;
	if (data.unlisted !== undefined) {
		const raw = String(data.unlisted).trim().toLowerCase();
		if (raw !== "true" && raw !== "false") {
			throw new DeckError(
				`unlisted は true か false です: ${String(data.unlisted)}`,
			);
		}
		unlisted = raw === "true";
	}
	if (event !== undefined && event.length === 0) {
		throw new DeckError("event が空です");
	}
	if (talkSlug !== undefined) {
		if (talkSlug.length === 0) {
			throw new DeckError("talkSlug が空です");
		}
		if (!SLUG_PATTERN.test(talkSlug)) {
			throw new DeckError(
				`talkSlug は英小文字・数字・ハイフンだけです: ${talkSlug}`,
			);
		}
	}
	let accent: string | undefined;
	let accentDeep: string | undefined;
	if (data.accent !== undefined) {
		const parsed = parseAccent(String(data.accent));
		accent = parsed.accent;
		accentDeep = parsed.accentDeep;
	}
	let effect: DeckEffect | undefined;
	if (data.effect !== undefined) {
		const raw = String(data.effect).trim().toLowerCase();
		if (!isDeckEffect(raw)) {
			throw new DeckError(`effect は snow です: ${String(data.effect)}`);
		}
		effect = raw;
	}
	return {
		title,
		date,
		description,
		slug,
		theme,
		...(accent ? { accent, accentDeep } : {}),
		...(effect ? { effect } : {}),
		...(event ? { event } : {}),
		...(talkSlug ? { talkSlug } : {}),
		...(unlisted ? { unlisted: true } : {}),
	};
}
function extractNotes(source: string): { notes: string; body: string } {
	const notes: string[] = [];
	const body = source
		.replace(NOTES_BLOCK, (_all, inner: string) => {
			notes.push(inner.replace(/^\s*\n/, "").trimEnd());
			return "\n";
		})
		.trim();
	return { notes: notes.join("\n\n").trim(), body };
}
async function parseSlide(
	source: string,
	slug: string,
	index: number,
	theme: ColorTheme,
): Promise<Slide> {
	let rest = source;
	let type: SlideType = "body";
	const typeMatch = rest.match(TYPE_AT_START);
	if (typeMatch) {
		if (!isSlideType(typeMatch[1])) {
			throw new DeckError(
				`スライド ${index + 1}: 未知の型です: ${typeMatch[1]}`,
			);
		}
		type = typeMatch[1];
		rest = rest.slice(typeMatch[0].length);
	}
	if (/<!--\s*type:/i.test(rest)) {
		throw new DeckError(
			`スライド ${index + 1}: type コメントは先頭に 1 つだけ置いてください`,
		);
	}
	const extracted = extractNotes(rest);
	rest = extracted.body;
	const toHtml = (markdown: string) => markdownToHtml(markdown, slug, theme);
	try {
		const columnParts = rest.split(COLUMN_MARK);
		if (type === "split") {
			if (columnParts.length !== 2) {
				throw new DeckError(
					`スライド ${index + 1}: split は <!-- column --> を 1 つだけ使って左右を分けます`,
				);
			}
			const left = await materializeSlideHtml(columnParts[0].trim(), toHtml);
			const right = await materializeSlideHtml(columnParts[1].trim(), toHtml);
			return {
				type,
				html: `<div class="split-pane">${left.html}</div><div class="split-pane">${right.html}</div>`,
				notes: extracted.notes,
				clicks: Math.max(left.clicks, right.clicks),
				columns: [left.html, right.html],

