	html: string,
	start: number,
): { html: string; extra: number } {
	const root = parse(html);
	const list = root.querySelector("ul, ol");
	if (!list) {
		throw new DeckError("<!-- clicks --> のあとにリストがありません");
	}

	let extra = 0;
