export async function fetchLinkCard(
	url: string,
	options: LinkCardFetchOptions = {},
): Promise<LinkCardData> {
	const parsed = parseLinkUrl(url);
	const href = parsed?.href ?? url;
	const fallback = fallbackLinkCard(href);
	if (!parsed) {
		return fallback;
	}

	const fetchImpl = options.fetch ?? fetch;
	try {
		const response = await fetchImpl(href, {
			headers: {
				accept: "text/html,application/xhtml+xml",
				"accept-language": "ja,en;q=0.8",
				"user-agent": USER_AGENT,
			},
			redirect: "follow",
			signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
		});
		if (!response.ok) {
			return fallback;
		}
		const contentType = response.headers.get("content-type") ?? "";
		if (contentType && !contentType.includes("html")) {
			return fallback;
		}
		const html = (await response.text()).slice(0, MAX_HTML_BYTES);
		const base = response.url || href;
		const card = fromHtml(href, html, base);
		return {
			...card,
			favicon: await resolveFavicon(card.domain, {
				fetch: fetchImpl,
				candidates: card.favicon ? [card.favicon] : [],
				pageUrl: base,
