import type { BlogEmbed } from "./embed-cache.ts";
import { matchStandaloneLinkBlock } from "./link-url.ts";
import { matchStandaloneSpotifyBlock } from "./spotify-url.ts";
import { matchStandaloneTweetBlock } from "./tweet-url.ts";
import { matchStandaloneYoutubeBlock } from "./youtube-url.ts";

/**
 * 段落のソースが「URL（または Markdown リンク）1 つだけ」なら埋め込みにする。
 * 判定は marked 版（`markdown.ts`）と同じ matcher を使い、X → YouTube → Spotify → リンクカードの順で決める。
 */
export function standaloneEmbed(source: string): BlogEmbed | null {
	const text = source.trim();
	if (text.length === 0 || text.includes("\n")) {
		return null;
	}
	const whole = (raw: string) => raw.trim() === text;

	const tweet = matchStandaloneTweetBlock(text);
	if (tweet && whole(tweet.raw)) {
		return { kind: "tweet", id: tweet.id, href: tweet.href };
	}
	const youtube = matchStandaloneYoutubeBlock(text);
	if (youtube && whole(youtube.raw)) {
		return { kind: "youtube", id: youtube.id, href: youtube.href };
	}
	const spotify = matchStandaloneSpotifyBlock(text);
	if (spotify && whole(spotify.raw)) {
		return { kind: "spotify", href: spotify.href };
	}
	const link = matchStandaloneLinkBlock(text);
	if (link && whole(link.raw)) {
		return { kind: "link", href: link.href };
	}
	return null;
}

import type { BlogEmbed } from "./embed-cache.ts";
import type { FaviconCache } from "./favicon.ts";
import { fetchLinkCard, linkCardHtml } from "./link-card.ts";
import { spotifyEmbedHtml } from "./spotify.ts";
import { fetchTweetEmbed, tweetEmbedHtml } from "./tweet.ts";
import { fetchYoutubeEmbed, youtubeEmbedHtml } from "./youtube.ts";

export type BlogEmbedFetchOptions = {
	fetch?: typeof fetch;
	favicons?: FaviconCache;
};

/**
 * ビルド時に埋め込み先を取得して HTML にする。取得に失敗したら各 builder のフォールバックを出す。
 */
export async function blogEmbedHtml(
	embed: BlogEmbed,
	options: BlogEmbedFetchOptions = {},
): Promise<string> {
	switch (embed.kind) {
		case "tweet":
			return tweetEmbedHtml(
				embed.href,
				await fetchTweetEmbed(embed.id, { fetch: options.fetch }),
			);
		case "youtube":
			return youtubeEmbedHtml(
				embed.href,
				await fetchYoutubeEmbed(embed.id, { fetch: options.fetch }),
			);
		case "spotify":
			return spotifyEmbedHtml(embed.href);
		case "link":
			return linkCardHtml(
				await fetchLinkCard(embed.href, {
					fetch: options.fetch,
					favicons: options.favicons,
				}),
			);
	}
}

const cache = new Map<string, Promise<string>>();
const favicons: FaviconCache = new Map();

/** 同じ URL はビルド中に 1 回だけ取りに行く（ページと RSS などで共有）。 */
export function cachedBlogEmbedHtml(embed: BlogEmbed): Promise<string> {
	const key = `${embed.kind}:${embed.href}`;
	let pending = cache.get(key);
	if (!pending) {
		pending = blogEmbedHtml(embed, { favicons });
		cache.set(key, pending);
	}
	return pending;
}

